def fnum(v):
    s = ('%.4f' % v).rstrip('0').rstrip('.')
    return s if '.' in s else s + '.0'


def build():
    lines = []
    names = ['ЭКОНОМИЧЕСКАЯ', 'СОЦИАЛЬНАЯ', 'ПОЛИТИЧЕСКАЯ', 'ПРОМЫШЛЕННАЯ']
    for b in range(4):
        lines.append('\t# ---------------- %s ----------------' % names[b])
        for t in range(12):
            opts = T[b][t]
            for k, (name, desc, fx, extra) in enumerate(opts):
                if b == 3 and 'growth_bonus' in fx:      # промышленная ветка даёт рост слабее: часть эффекта идёт через прибыль, безработицу, экологию
                    fx = dict(fx, growth_bonus=round(fx['growth_bonus'] * 0.7, 3))
                tid = BRANCH_LETTER[b] + str(t) + (('abc'[k]) if len(opts) > 1 else '')
                cost = int(round(BASE * GROW ** t * OPT_COST[k] / 5.0)) * 5
                fxs = ', '.join('"%s": %s' % (key, fnum(val)) for key, val in fx.items())
                ex = ''
                for key in ('rs', 'cp'):
                    if key in extra:
                        ex += ', "%s": %s' % (key, fnum(extra[key]))
                if 'req' in extra:
                    ex += ', "req": [%s]' % ', '.join('"%s"' % r for r in extra['req'])
                lines.append('\t{"id": "%s", "b": %d, "t": %d, "yr": %d, "cost": %d, "name": "%s", "d": "%s",\n\t\t"fx": {%s}%s},'
                             % (tid, b, t, TIER_YR[t], cost, name, desc, fxs, ex))
    return '\n'.join(lines)


def main():
    s = open(PATH, encoding='utf-8').read()
    a = s.index('const TECHS := [')
    b = s.index('\n]\n', a)
    head = s[:a]
    new = 'const TECHS := [\n' + build() + s[b:]
    open(PATH, 'w', encoding='utf-8').write(head + new)
    n = sum(len(v) for br in T.values() for v in br.values())
    print('технологий:', n)


